//! Parity tests against the Go original (`github.com/junhinhow/charm-nav`).
//!
//! The golden file is generated by the Go program in
//! `reference/go/charm-nav/cmd/parity`, which exercises the same public API
//! in the same order.

use charm_nav::{Breadcrumb, Sidebar, Tabs};
use charm_parity::assert_golden;

/// Small helper that mirrors the `out` builder of the Go parity program.
struct Output(String);

impl Output {
    fn section(&mut self, name: &str) {
        self.0.push_str("=== ");
        self.0.push_str(name);
        self.0.push_str(" ===\n");
    }

    fn block(&mut self, content: &str) {
        self.0.push_str(content);
        self.0.push('\n');
    }

    fn line(&mut self, content: &str) {
        self.0.push_str(content);
        self.0.push('\n');
    }
}

/// Builds the very same output as the Go parity program.
fn build_output() -> String {
    let mut out = Output(String::new());

    let mut tabs = Tabs::new(&["Home", "Settings", "About"]);

    out.section("tabs padrao");
    out.block(&tabs.render());
    out.line(&format!("active={}", tabs.active()));
    out.line(&format!("items={}", tabs.items().join(",")));

    out.section("tabs apos next");
    tabs.next();
    out.block(&tabs.render());
    out.line(&format!("active={}", tabs.active()));

    out.section("tabs apos previous");
    tabs.previous();
    out.block(&tabs.render());
    out.line(&format!("active={}", tabs.active()));

    out.section("tabs previous no inicio");
    tabs.previous();
    out.block(&tabs.render());
    out.line(&format!("active={}", tabs.active()));

    out.section("tabs set active fora do intervalo");
    tabs.set_active(99);
    out.line(&format!("active={}", tabs.active()));

    out.section("tabs set active valido");
    tabs.set_active(2);
    out.block(&tabs.render());
    out.line(&format!("active={}", tabs.active()));

    out.section("tabs vazio");
    let mut empty_tabs = Tabs::new(&[]);
    out.block(&empty_tabs.render());
    empty_tabs.next();
    empty_tabs.previous();
    out.line(&format!("active={}", empty_tabs.active()));

    let mut sidebar = Sidebar::new(&["Dashboard", "Users", "Settings", "Logs"]);

    out.section("sidebar padrao");
    sidebar.set_selected(1);
    out.block(&sidebar.render());
    out.line(&format!("selected={}", sidebar.selected()));

    out.section("sidebar apos next");
    sidebar.next();
    out.block(&sidebar.render());
    out.line(&format!("selected={}", sidebar.selected()));

    out.section("sidebar apos previous");
    sidebar.previous();
    out.block(&sidebar.render());
    out.line(&format!("selected={}", sidebar.selected()));

    out.section("sidebar previous no inicio");
    let mut fresh = Sidebar::new(&["Dashboard", "Users", "Settings", "Logs"]);
    fresh.previous();
    out.block(&fresh.render());
    out.line(&format!("selected={}", fresh.selected()));

    out.section("sidebar set selected fora do intervalo");
    fresh.set_selected(42);
    out.line(&format!("selected={}", fresh.selected()));

    out.section("sidebar largura e cursor customizados");
    let mut custom = Sidebar::new(&["Dashboard", "Users"]);
    custom.width = 30;
    custom.cursor = "> ".to_string();
    out.block(&custom.render());

    out.section("sidebar vazio");
    let empty_sidebar = Sidebar::new(&[]);
    out.block(&empty_sidebar.render());
    out.line(&format!("selected={}", empty_sidebar.selected()));

    let mut breadcrumb = Breadcrumb::new(&["Home", "Settings"]);

    out.section("breadcrumb padrao");
    breadcrumb.push("Profile");
    out.block(&breadcrumb.render());
    out.line(&format!("items={}", breadcrumb.items().join(",")));

    out.section("breadcrumb apos pop");
    out.line(&format!("pop={}", breadcrumb.pop()));
    out.block(&breadcrumb.render());

    out.section("breadcrumb pop vazio");
    let mut empty_breadcrumb = Breadcrumb::new(&[]);
    out.line(&format!("pop={}", empty_breadcrumb.pop()));
    out.block(&empty_breadcrumb.render());

    out.0
}

#[test]
fn nav_matches_the_go_original() {
    assert_golden("nav", &build_output());
}
